//! Tauri build hook: generates the capability schemas + embeds the config so
//! `tauri::generate_context!()` in `src/lib.rs` has everything it needs.

fn main() {
    println!("cargo:rerun-if-changed=windows-app-manifest.xml");
    // `frontendDist` is generated by the workspace Bun build. Track the source
    // so Cargo/Tauri rebuilds after a Material shell change.
    println!("cargo:rerun-if-changed=../../packages/app-ui");

    // Tao retains control of DPI awareness, including its PerMonitorV2 fallback.
    let windows = tauri_build::WindowsAttributes::new()
        .app_manifest(include_str!("windows-app-manifest.xml"));
    tauri_build::try_build(tauri_build::Attributes::new().windows_attributes(windows))
        .expect("failed to build Tauri resources");
}
